// ── Whitelist check ──────────────────────────────────────────────
const allowedChatId = $env['TELEGRAM_ALLOWED_CHAT_ID'];
const msg = $input.first().json.message;
if (!msg) throw new Error('No message in update');

const chatId = String(msg.chat.id);
if (chatId !== String(allowedChatId)) {
  return [{ json: { skip: true, reason: 'not_allowed', chatId } }];
}

// ── Determine message type ────────────────────────────────────────
let promptText = '';
let hasPhoto = false;
let hasVoice = false;
let fileId = null;
let mimeType = 'image/jpeg';

if (msg.text) {
  promptText = msg.text;
} else if (msg.photo) {
  hasPhoto = true;
  // Telegram returns array sorted by size; take the largest
  const photos = msg.photo;
  fileId = photos[photos.length - 1].file_id;
  promptText = msg.caption || '(прикреплено фото)';
} else if (msg.voice) {
  hasVoice = true;
  fileId = msg.voice.file_id;
  mimeType = msg.voice.mime_type || 'audio/ogg';
  promptText = ''; // will be filled after STT or fallback
} else {
  promptText = msg.caption || '[неизвестный тип сообщения]';
}

return [{
  json: {
    skip: false,
    chatId,
    messageId: msg.message_id,
    promptText,
    hasPhoto,
    hasVoice,
    fileId,
    mimeType
  }
}];

// Convert downloaded file binary to base64
const items = $input.all();
const item = items[0];
const binaryKey = Object.keys(item.binary || {})[0] || 'data';
const binaryData = item.binary[binaryKey];
const base64 = binaryData.data; // n8n stores base64 in .data
const mimeType = binaryData.mimeType || 'image/jpeg';

// Pull through the upstream context (chatId, promptText, etc.)
const upstream = item.json;

return [{
  json: {
    ...upstream,
    imageBase64: base64,
    imageMimeType: mimeType
  }
}];

// MVP: STT not implemented — reply immediately and stop
const item = $input.first().json;
return [{
  json: {
    ...item,
    voiceDeclined: true,
    declineMessage: '🎙 Голосовые сообщения пока не поддерживаются в этой версии. Напиши текстом или пришли скрин.'
  }
}];

// ── Merge branches into one payload for Create Agent ─────────────
// Called from: photo branch (has imageBase64) OR plain-text branch
const item = $input.first().json;

const systemContext = `
Ты — Cursor Cloud Agent, привязанный к проекту Languages on site / EnglishOnSite.
Рабочая директория: ~/Developer/EnglishOnSite/
Правки только внутри этой директории — не трогать другие проекты.
Формат ответа:
1. Что сделано
2. Что осталось / что ещё нужно
3. Blockers (если есть)
`.trim();

const userText = item.promptText || '(нет текста)';
const fullPrompt = `${systemContext}\n\n---\nЗапрос пользователя:\n${userText}`;

const payload = {
  chatId: item.chatId,
  promptText: fullPrompt,
  images: []
};

if (item.imageBase64) {
  payload.images = [{
    data: item.imageBase64,
    mimeType: item.imageMimeType || 'image/jpeg'
  }];
}

return [{ json: payload }];

