// Extract agentId and runId from Create Agent response
const resp = $input.first().json;
// API returns { id, latestRunId } or { id, runs: [{id}] }
const agentId = resp.id;
const runId = resp.latestRunId || (resp.runs && resp.runs[0] && resp.runs[0].id);

if (!agentId) throw new Error('No agentId in Create Agent response: ' + JSON.stringify(resp));

// Carry chatId through (from two steps back via sticky)
const chatId = $('Build Agent payload').first().json.chatId;

return [{
  json: {
    agentId,
    runId,
    chatId,
    pollCount: 0,
    maxPolls: 40
  }
}];

// Merge poll response with loop state
const pollResp = $input.first().json;
const loopState = $('Wait 25s').first().json;

const status = pollResp.status || pollResp.state || 'UNKNOWN';
const terminalStatuses = ['FINISHED', 'ERROR', 'CANCELLED', 'EXPIRED', 'FAILED'];
const pendingStatuses = ['CREATING', 'RUNNING', 'WAITING_FOR_BACKGROUND_WORK', 'PENDING', 'QUEUED'];

const newPollCount = (loopState.pollCount || 0) + 1;
const maxPolls = loopState.maxPolls || 40;
const timedOut = newPollCount >= maxPolls;

return [{
  json: {
    agentId: loopState.agentId,
    runId: loopState.runId,
    chatId: loopState.chatId,
    pollCount: newPollCount,
    maxPolls,
    status,
    result: pollResp.result || pollResp.output || null,
    isTerminal: terminalStatuses.includes(status.toUpperCase()) || timedOut,
    timedOut,
    rawResponse: pollResp
  }
}];

// Loop back: carry state to Wait node
const item = $input.first().json;
return [{ json: item }];

// Format final message
const item = $input.first().json;
const MAX_LEN = 3500;

let text = '';
if (item.timedOut) {
  text = `⏰ Timeout: агент не завершился за ${item.maxPolls * 25} сек. Статус: ${item.status}\nПроверь вручную: agentId=${item.agentId}`;
} else if (['ERROR', 'CANCELLED', 'EXPIRED', 'FAILED'].includes((item.status || '').toUpperCase())) {
  text = `❌ Агент завершился со статусом *${item.status}*\n`;
  if (item.result) text += String(item.result).slice(0, MAX_LEN - text.length);
} else {
  const result = item.result ? String(item.result) : '(нет текста в поле result)';
  text = `✅ *Агент завершил работу*\n\n${result}`.slice(0, MAX_LEN);
}

return [{ json: { chatId: item.chatId, text } }];
